('omni-practitioner', $json${"fr":"praticien-hypnose-omni","de":"omni-hypnose-praktiker","en":"omni-hypnosis-practitioner"}$json$::jsonb, $json${"fr":"Praticien·ne en Hypnose OMNI®","de":"OMNI® Hypnosepraktiker·in","en":"OMNI® Hypnosis Practitioner"}$json$::jsonb, $json${"fr":"La formation de base du cursus, fondée sur l’hypnose elmanienne et une approche pragmatique, rapide et orientée solution.","de":"Die Grundausbildung des Lehrgangs, basierend auf elmanischer Hypnose und einem pragmatischen, schnellen, lösungsorientierten Ansatz.","en":"The curriculum’s foundation course, based on Elmanian hypnosis and a pragmatic, rapid, solution-focused approach."}$json$::jsonb, $json${"fr":"La formation de Praticien·ne en Hypnose OMNI® constitue la base de ce cursus. Basée sur l’hypnose elmanienne, la méthode OMNI® est reconnue pour son approche pragmatique orientée solution, la rapidité et l’efficacité de ses techniques, ainsi que ses formats thérapeutiques innovants. Découvrez l’hypnose comme un outil de travail qui n’a quasiment pas de limite dans son application.","de":"Die Ausbildung zum OMNI® Hypnosepraktiker bildet die Grundlage dieses Lehrgangs. Die auf elmanischer Hypnose basierende OMNI® Methode ist für ihren pragmatischen, lösungsorientierten Ansatz, ihre schnellen und wirksamen Techniken sowie innovative Therapieformate bekannt. Entdecken Sie Hypnose als vielseitiges Arbeitsinstrument mit nahezu unbegrenzten Anwendungsmöglichkeiten.","en":"The OMNI® Hypnosis Practitioner course is the foundation of this curriculum. Based on Elmanian hypnosis, the OMNI® method is known for its pragmatic, solution-focused approach, rapid and effective techniques, and innovative therapeutic formats. Discover hypnosis as a highly versatile professional tool with almost unlimited applications."}$json$::jsonb, $json${"fr":"Toute personne souhaitant apprendre l’hypnose de manière professionnelle, dès 18 ans. Aucun prérequis en hypnose n’est nécessaire.","de":"Für alle Personen ab 18 Jahren, die Hypnose professionell erlernen möchten. Hypnose-Vorkenntnisse sind nicht erforderlich.","en":"For anyone aged 18 or over who wants to learn hypnosis professionally. No previous hypnosis training is required."}$json$::jsonb, $json${"fr":"10 jours · 80 heures","de":"10 Tage · 80 Stunden","en":"10 days · 80 hours"}$json$::jsonb, $json${"fr":"Fribourg","de":"Freiburg","en":"Fribourg"}$json$::jsonb, 3490, 'foundation', true, 0),
('master-practitioner', $json${"fr":"maitre-praticien-hypnose-elmanienne","de":"elmanische-hypnose-master","en":"elmanian-hypnosis-master-practitioner"}$json$::jsonb, $json${"fr":"Maître Praticien·ne en Hypnose Elmanienne","de":"Master-Praktiker·in in elmanischer Hypnose","en":"Master Practitioner in Elmanian Hypnosis"}$json$::jsonb, $json${"fr":"Le deuxième niveau du cursus pour approfondir, spécialiser et professionnaliser les compétences acquises comme praticien·ne OMNI®.","de":"Die zweite Stufe des Lehrgangs zur Vertiefung, Spezialisierung und Professionalisierung der OMNI®-Praxis.","en":"The curriculum’s second level, designed to deepen, specialise and professionalise the skills gained as an OMNI® practitioner."}$json$::jsonb, $json${"fr":"La formation de Maître Praticien·ne se compose de six modules avancés de deux à trois jours sur les addictions, le sport, les maladies, les enfants, les troubles anxieux et les techniques avancées en hypnose. Le diplôme de Praticien·ne en Hypnose OMNI® est requis. Cette formation correspond au Cycle 2 ASCA.","de":"Die Master-Ausbildung besteht aus sechs fortgeschrittenen Modulen von je zwei bis drei Tagen zu Sucht, Sport, Krankheiten, Kindern, Angststörungen und fortgeschrittenen Hypnosetechniken. Das OMNI®-Praktikerdiplom ist Voraussetzung. Die Ausbildung entspricht dem ASCA-Zyklus 2.","en":"The Master Practitioner programme consists of six advanced two- or three-day modules covering addictions, sport, illness, children, anxiety disorders and advanced hypnosis techniques. The OMNI® Hypnosis Practitioner diploma is required. This programme corresponds to ASCA Cycle 2."}$json$::jsonb, $json${"fr":"Praticien·ne·s en Hypnose OMNI® souhaitant pratiquer l’hypnose thérapeutique de manière professionnelle.","de":"OMNI® Hypnosepraktiker·innen, die therapeutische Hypnose professionell ausüben möchten.","en":"OMNI® hypnosis practitioners who want to practise therapeutic hypnosis professionally."}$json$::jsonb, $json${"fr":"15 jours · 220 heures","de":"15 Tage · 220 Stunden","en":"15 days · 220 hours"}$json$::jsonb, $json${"fr":"Fribourg","de":"Freiburg","en":"Fribourg"}$json$::jsonb, 4950, 'advanced', true, 1),
('advanced-techniques', $json${"fr":"hypnose-techniques-avancees","de":"hypnose-fortgeschrittene-techniken","en":"advanced-hypnosis-techniques"}$json$::jsonb, $json${"fr":"Techniques avancées","de":"Fortgeschrittene Techniken","en":"Advanced Techniques"}$json$::jsonb, $json${"fr":"Renforcez votre assurance et votre créativité en approfondissant les méthodes les plus avancées de l’hypnose.","de":"Stärken Sie Sicherheit und Kreativität durch die Vertiefung der fortgeschrittensten Hypnosemethoden.","en":"Build confidence and creativity by deepening your knowledge of the most advanced hypnosis methods."}$json$::jsonb, $json${"fr":"Cette formation vise à renforcer l’assurance et la créativité des hypnothérapeutes. Vous approfondirez les techniques de régression, explorerez les états d’hypnose profonde et apprendrez à exploiter les phénomènes hypnotiques complexes afin de personnaliser votre approche face à des problématiques plus exigeantes.","de":"Diese Ausbildung stärkt Sicherheit und Kreativität von Hypnosetherapeutinnen und -therapeuten. Sie vertiefen Regressionstechniken, erforschen tiefe Hypnosezustände und lernen, komplexe hypnotische Phänomene für anspruchsvollere Anliegen individuell einzusetzen.","en":"This course strengthens hypnotherapists’ confidence and creativity. You will deepen regression techniques, explore profound hypnotic states and learn to use complex hypnotic phenomena to tailor your approach to more demanding issues."}$json$::jsonb, $json${"fr":"Praticien·ne·s en hypnose souhaitant aller au-delà des fondamentaux.","de":"Hypnosepraktiker·innen, die über die Grundlagen hinausgehen möchten.","en":"Hypnosis practitioners who want to go beyond the fundamentals."}$json$::jsonb, $json${"fr":"3 jours · 24 heures","de":"3 Tage · 24 Stunden","en":"3 days · 24 hours"}$json$::jsonb, $json${"fr":"Fribourg","de":"Freiburg","en":"Fribourg"}$json$::jsonb, 890, 'advanced', true, 2),
('solution-focused-interview', $json${"fr":"entretien-oriente-solution","de":"loesungsorientiertes-gespraech","en":"solution-focused-interview"}$json$::jsonb, $json${"fr":"Entretien Orienté Solution","de":"Lösungsorientiertes Gespräch","en":"Solution-Focused Interview"}$json$::jsonb, $json${"fr":"Dynamisez les entretiens préliminaires avec une méthode de thérapie brève adaptée aux besoins des hypnothérapeutes.","de":"Gestalten Sie Vorgespräche wirksamer mit einer auf Hypnosetherapie zugeschnittenen lösungsorientierten Kurzzeitmethode.","en":"Make preliminary interviews more effective with a brief-therapy method adapted to hypnotherapists’ needs."}$json$::jsonb, $json${"fr":"Cette formation transforme les entretiens préliminaires et structure les consultations de manière plus fluide et percutante. Les techniques enseignées permettent d’intervenir de façon ciblée et stratégique, en associant thérapie brève et coaching pour accompagner les client·e·s plus rapidement et durablement.","de":"Diese Ausbildung verwandelt Vorgespräche und strukturiert Sitzungen flüssiger und wirkungsvoller. Die vermittelten Techniken verbinden Kurzzeittherapie und Coaching für eine gezielte, strategische und nachhaltige Begleitung.","en":"This course reshapes preliminary interviews and gives consultations a clearer, more effective structure. Its techniques combine brief therapy and coaching for targeted, strategic and lasting client support."}$json$::jsonb, $json${"fr":"Hypnothérapeutes souhaitant renforcer leurs entretiens et leur posture de coaching.","de":"Hypnosetherapeut·innen, die Gesprächsführung und Coachinghaltung stärken möchten.","en":"Hypnotherapists who want to strengthen interviewing and coaching skills."}$json$::jsonb, $json${"fr":"2 jours · 16 heures","de":"2 Tage · 16 Stunden","en":"2 days · 16 hours"}$json$::jsonb, $json${"fr":"Fribourg","de":"Freiburg","en":"Fribourg"}$json$::jsonb, 580, 'advanced', true, 3),
('anxiety-hypnosis', $json${"fr":"troubles-anxieux-hypnose","de":"angststoerungen-hypnose","en":"anxiety-disorders-hypnosis"}$json$::jsonb, $json${"fr":"Troubles Anxieux & Hypnose","de":"Angststörungen & Hypnose","en":"Anxiety Disorders & Hypnosis"}$json$::jsonb, $json${"fr":"Maîtrisez l’accompagnement de l’anxiété, des TOC, crises d’angoisse et phobies par une approche intégrative.","de":"Begleiten Sie Angst, Zwangsstörungen, Panikattacken und Phobien mit einem integrativen Ansatz.","en":"Learn to address anxiety, OCD, panic attacks and phobias through an integrative approach."}$json$::jsonb, $json${"fr":"Cette formation propose une approche innovante et multidisciplinaire de l’hypnose intégrative pour accompagner l’anxiété généralisée, les troubles obsessionnels compulsifs, les crises d’angoisse et les phobies. Elle associe compréhension clinique, stratégie thérapeutique et outils hypnotiques concrets.","de":"Diese Ausbildung vermittelt einen innovativen, multidisziplinären Ansatz integrativer Hypnose für generalisierte Angst, Zwangsstörungen, Panikattacken und Phobien. Sie verbindet klinisches Verständnis, therapeutische Strategie und konkrete Hypnosewerkzeuge.","en":"This course offers an innovative, multidisciplinary integrative-hypnosis approach to general anxiety, obsessive-compulsive disorders, panic attacks and phobias. It combines clinical understanding, therapeutic strategy and practical hypnotic tools."}$json$::jsonb, $json${"fr":"Hypnothérapeutes et professionnel·le·s de l’accompagnement formé·e·s à l’hypnose.","de":"Hypnosetherapeut·innen und in Hypnose ausgebildete Fachpersonen.","en":"Hypnotherapists and helping professionals trained in hypnosis."}$json$::jsonb, $json${"fr":"3 jours · 24 heures","de":"3 Tage · 24 Stunden","en":"3 days · 24 hours"}$json$::jsonb, $json${"fr":"Fribourg","de":"Freiburg","en":"Fribourg"}$json$::jsonb, 890, 'advanced', true, 4),
('sport-hypnosis', $json${"fr":"sport-hypnose","de":"sport-und-hypnose","en":"sport-hypnosis"}$json$::jsonb, $json${"fr":"Sport & Hypnose","de":"Sport & Hypnose","en":"Sport & Hypnosis"}$json$::jsonb, $json${"fr":"Des techniques hypnotiques pour soutenir, renforcer et optimiser la performance sportive.","de":"Hypnosetechniken zur Unterstützung, Stärkung und Optimierung sportlicher Leistung.","en":"Hypnotic techniques to support, strengthen and optimise sporting performance."}$json$::jsonb, $json${"fr":"Cette formation avancée présente une gamme de techniques d’hypnose appliquées au sport : préparation mentale, concentration, confiance, gestion du stress et optimisation de la performance.","de":"Diese Fortbildung vermittelt Hypnosetechniken für den Sport: mentale Vorbereitung, Konzentration, Selbstvertrauen, Stressbewältigung und Leistungsoptimierung.","en":"This advanced course presents hypnosis techniques for sport: mental preparation, concentration, confidence, stress management and performance optimisation."}$json$::jsonb, $json${"fr":"Hypnothérapeutes, coachs et professionnel·le·s accompagnant des sportif·ve·s.","de":"Hypnosetherapeut·innen, Coaches und Fachpersonen in der Sportbegleitung.","en":"Hypnotherapists, coaches and professionals supporting athletes."}$json$::jsonb, $json${"fr":"2 jours · 16 heures","de":"2 Tage · 16 Stunden","en":"2 days · 16 hours"}$json$::jsonb, $json${"fr":"Fribourg","de":"Freiburg","en":"Fribourg"}$json$::jsonb, 580, 'advanced', true, 5),
('children-hypnosis', $json${"fr":"enfants-hypnose","de":"kinder-hypnose","en":"children-hypnosis"}$json$::jsonb, $json${"fr":"Enfants & Hypnose","de":"Kinder & Hypnose","en":"Children & Hypnosis"}$json$::jsonb, $json${"fr":"Des techniques adaptées aux enfants, aux adolescent·e·s, à leur imaginaire et à la dynamique familiale.","de":"Techniken für Kinder und Jugendliche, ihre Vorstellungskraft und die Familiendynamik.","en":"Techniques adapted to children, teenagers, their imagination and family dynamics."}$json$::jsonb, $json${"fr":"Cette formation est destinée aux thérapeutes souhaitant apprendre des techniques d’accompagnement adaptées aux jeunes, à leur langage, à leur imaginaire et à la dynamique familiale.","de":"Diese Ausbildung richtet sich an Therapeutinnen und Therapeuten, die altersgerechte Begleittechniken für junge Menschen, ihre Sprache, Vorstellungskraft und Familiendynamik erlernen möchten.","en":"This course is for therapists who want to learn support techniques adapted to young people, their language, imagination and family dynamics."}$json$::jsonb, $json${"fr":"Thérapeutes et praticien·ne·s en hypnose souhaitant accompagner enfants et adolescent·e·s.","de":"Therapeut·innen und Hypnosepraktiker·innen, die Kinder und Jugendliche begleiten möchten.","en":"Therapists and hypnosis practitioners who want to support children and teenagers."}$json$::jsonb, $json${"fr":"2 jours · 16 heures","de":"2 Tage · 16 Stunden","en":"2 days · 16 hours"}$json$::jsonb, $json${"fr":"Fribourg","de":"Freiburg","en":"Fribourg"}$json$::jsonb, 580, 'advanced', true, 6),
('addictions-hypnosis', $json${"fr":"addictions-hypnose","de":"sucht-hypnose","en":"addictions-hypnosis"}$json$::jsonb, $json${"fr":"Addictions & Hypnose","de":"Sucht & Hypnose","en":"Addictions & Hypnosis"}$json$::jsonb, $json${"fr":"L’hypnose au service du sevrage face au tabagisme, à l’alcool, aux drogues et aux dépendances comportementales.","de":"Hypnose zur Unterstützung bei Tabak-, Alkohol-, Drogen- und Verhaltensabhängigkeiten.","en":"Hypnosis to support withdrawal from tobacco, alcohol, drugs and behavioural addictions."}$json$::jsonb, $json${"fr":"L’hypnose peut jouer un rôle clé dans le processus de sevrage. Cette formation aborde le tabagisme, l’alcoolisme, la toxicomanie, la dépendance à Internet et d’autres comportements addictifs avec des outils concrets et une stratégie d’accompagnement structurée.","de":"Hypnose kann im Entwöhnungsprozess eine wichtige Rolle spielen. Die Ausbildung behandelt Tabak, Alkohol, Drogen, Internetsucht und weitere Abhängigkeiten mit konkreten Werkzeugen und einer strukturierten Begleitstrategie.","en":"Hypnosis can play a key role in withdrawal. This course addresses tobacco, alcohol, drugs, internet dependency and other addictive behaviours with practical tools and a structured support strategy."}$json$::jsonb, $json${"fr":"Hypnothérapeutes souhaitant accompagner les problématiques de dépendance.","de":"Hypnosetherapeut·innen, die Menschen bei Abhängigkeiten begleiten möchten.","en":"Hypnotherapists who want to support clients with dependency issues."}$json$::jsonb, $json${"fr":"2 jours · 16 heures","de":"2 Tage · 16 Stunden","en":"2 days · 16 hours"}$json$::jsonb, $json${"fr":"Fribourg","de":"Freiburg","en":"Fribourg"}$json$::jsonb, 580, 'advanced', true, 7),
('illness-hypnosis', $json${"fr":"maladies-hypnose","de":"krankheiten-hypnose","en":"illness-hypnosis"}$json$::jsonb, $json${"fr":"Maladies & Hypnose","de":"Krankheiten & Hypnose","en":"Illness & Hypnosis"}$json$::jsonb, $json${"fr":"Une formation interactive pour les problématiques somatiques et psychosomatiques rencontrées en cabinet.","de":"Eine interaktive Ausbildung zu somatischen und psychosomatischen Anliegen in der Praxis.","en":"An interactive course for somatic and psychosomatic issues encountered in practice."}$json$::jsonb, $json${"fr":"Sous la forme d’un cours interactif, cette formation avancée s’adresse aux hypnothérapeutes confronté·e·s à des problématiques somatiques ou psychosomatiques. Elle aide à structurer un accompagnement adapté, complémentaire et responsable.","de":"Diese interaktive Fortbildung richtet sich an Hypnosetherapeutinnen und -therapeuten, die mit somatischen oder psychosomatischen Anliegen arbeiten. Sie hilft, eine passende, ergänzende und verantwortungsvolle Begleitung zu gestalten.","en":"This interactive advanced course is for hypnotherapists working with somatic or psychosomatic issues. It helps structure suitable, complementary and responsible support."}$json$::jsonb, $json${"fr":"Hypnothérapeutes rencontrant des problématiques somatiques ou psychosomatiques.","de":"Hypnosetherapeut·innen mit somatischen oder psychosomatischen Anliegen in der Praxis.","en":"Hypnotherapists encountering somatic or psychosomatic issues."}$json$::jsonb, $json${"fr":"2 jours · 16 heures","de":"2 Tage · 16 Stunden","en":"2 days · 16 hours"}$json$::jsonb, $json${"fr":"Fribourg","de":"Freiburg","en":"Fribourg"}$json$::jsonb, 580, 'advanced', true, 8),
('professional-practice-final-exam', $json${"fr":"pratique-professionnelle-examen-final","de":"berufspraxis-abschlusspruefung","en":"professional-practice-final-exam"}$json$::jsonb, $json${"fr":"Pratique professionnelle accompagnée & Examen Final","de":"Begleitete Berufspraxis & Abschlussprüfung","en":"Supervised Professional Practice & Final Exam"}$json$::jsonb, $json${"fr":"Validez les acquis du cursus et votre maîtrise du processus thérapeutique pour obtenir le diplôme de Maître Praticien·ne.","de":"Validieren Sie Ihre Kompetenzen und den therapeutischen Prozess für das Master-Praktiker-Diplom.","en":"Validate your curriculum knowledge and mastery of the therapeutic process for the Master Practitioner diploma."}$json$::jsonb, $json${"fr":"Cette étape valide les acquis du cursus de Maître Praticien·ne en Hypnose Elmanienne. Elle comprend 90 heures de pratique professionnelle documentée, 10 heures de rédaction et de mentoring, puis une journée d’examen final de 8 heures. La réussite est indispensable à l’obtention du diplôme et à la validation du Cycle 2 ASCA.","de":"Dieser Schritt validiert die Kompetenzen des Lehrgangs. Er umfasst 90 Stunden dokumentierte Berufspraxis, 10 Stunden schriftliche Arbeit und Mentoring sowie einen achtstündigen Prüfungstag. Das Bestehen ist Voraussetzung für das Diplom und die Anerkennung des ASCA-Zyklus 2.","en":"This stage validates the Master Practitioner curriculum. It includes 90 hours of documented professional practice, 10 hours of writing and mentoring, and an eight-hour final examination day. Passing is required for the diploma and ASCA Cycle 2 validation."}$json$::jsonb, $json${"fr":"Participant·e·s au cursus de Maître Praticien·ne ayant achevé les modules requis.","de":"Teilnehmende des Master-Lehrgangs nach Abschluss der erforderlichen Module.","en":"Master Practitioner participants who have completed the required modules."}$json$::jsonb, $json${"fr":"108 heures · dont 1 jour d’examen","de":"108 Stunden · davon 1 Prüfungstag","en":"108 hours · including 1 exam day"}$json$::jsonb, $json${"fr":"Fribourg","de":"Freiburg","en":"Fribourg"}$json$::jsonb, 1150, 'advanced', true, 9),
('transgenerational-mia', $json${"fr":"hypnose-transgenerationnelle-methode-mia","de":"transgenerationale-hypnose-mia","en":"transgenerational-hypnosis-mia"}$json$::jsonb, $json${"fr":"Hypnose Transgénérationnelle — Méthode M.I.A.®","de":"Transgenerationale Hypnose — M.I.A.®-Methode","en":"Transgenerational Hypnosis — M.I.A.® Method"}$json$::jsonb, $json${"fr":"Une approche rigoureuse et sensible des dynamiques transgénérationnelles, des héritages inconscients et de la libération symbolique.","de":"Ein sorgfältiger, sensibler Ansatz zu transgenerationalen Dynamiken, unbewussten Vermächtnissen und symbolischer Befreiung.","en":"A rigorous, sensitive approach to transgenerational dynamics, unconscious legacies and symbolic release."}$json$::jsonb, $json${"fr":"Cette formation exclusive propose une immersion dans les dynamiques transgénérationnelles, les héritages inconscients et les protocoles de libération symbolique. La méthode M.I.A.® associe hypnose, rituels thérapeutiques, questionnement, kinésiologie et approche systémique des lignées familiales.","de":"Diese exklusive Ausbildung vertieft transgenerationale Dynamiken, unbewusste Vermächtnisse und Protokolle symbolischer Befreiung. Die M.I.A.®-Methode verbindet Hypnose, therapeutische Rituale, Fragetechniken, Kinesiologie und einen systemischen Blick auf Familienlinien.","en":"This exclusive course explores transgenerational dynamics, unconscious legacies and symbolic-release protocols. The M.I.A.® method combines hypnosis, therapeutic rituals, questioning tools, kinesiology and a systemic approach to family lineages."}$json$::jsonb, $json${"fr":"Hypnothérapeutes souhaitant enrichir leur pratique d’une approche transgénérationnelle.","de":"Hypnosetherapeut·innen, die ihre Praxis um einen transgenerationalen Ansatz erweitern möchten.","en":"Hypnotherapists who want to add a transgenerational approach to their practice."}$json$::jsonb, $json${"fr":"4 + 2 jours · 48 heures","de":"4 + 2 Tage · 48 Stunden","en":"4 + 2 days · 48 hours"}$json$::jsonb, $json${"fr":"Fribourg","de":"Freiburg","en":"Fribourg"}$json$::jsonb, 1890, 'advanced', false, 10),
('medical-hypnosis-m1', $json${"fr":"hypnose-medicale-techniques-base","de":"medizinische-hypnose-grundtechniken","en":"medical-hypnosis-foundations"}$json$::jsonb, $json${"fr":"M1 | Techniques de base","de":"M1 | Grundtechniken","en":"M1 | Foundation Techniques"}$json$::jsonb, $json${"fr":"Apprenez les techniques de base de l’hypnose médicale elmanienne et intégrez-les à votre pratique quotidienne.","de":"Erlernen Sie die Grundlagen der elmanischen medizinischen Hypnose für den Berufsalltag.","en":"Learn the foundations of Elmanian medical hypnosis and integrate them into daily practice."}$json$::jsonb, $json${"fr":"Ce premier module est consacré aux techniques de base de l’hypnose médicale elmanienne. Vous développerez l’attitude et l’assurance nécessaires pour choisir les techniques appropriées et intégrer l’hypnose à votre routine quotidienne, avec un minimum d’effort et un maximum d’effet.","de":"Das erste Modul vermittelt die Grundlagen der elmanischen medizinischen Hypnose. Sie entwickeln Haltung und Sicherheit, um geeignete Techniken auszuwählen und Hypnose mit möglichst wenig Aufwand und grosser Wirkung in den Berufsalltag zu integrieren.","en":"This first module covers the foundations of Elmanian medical hypnosis. You will develop the attitude and confidence to select appropriate techniques and integrate hypnosis into daily practice with minimal effort and maximum effect."}$json$::jsonb, $json${"fr":"Professionnel·le·s de la santé souhaitant intégrer l’hypnose à leur pratique.","de":"Gesundheitsfachpersonen, die Hypnose in ihre Arbeit integrieren möchten.","en":"Healthcare professionals who want to integrate hypnosis into their practice."}$json$::jsonb, $json${"fr":"3 jours · 24 heures","de":"3 Tage · 24 Stunden","en":"3 days · 24 hours"}$json$::jsonb, $json${"fr":"Fribourg","de":"Freiburg","en":"Fribourg"}$json$::jsonb, 1450, 'medical', true, 11),
('medical-hypnosis-dental-m2', $json${"fr":"hypnose-medicale-dentaire-m2","de":"medizinische-hypnose-zahnmedizin-m2","en":"medical-hypnosis-dental-m2"}$json$::jsonb, $json${"fr":"M2 | Spécialisation Hypnose Dentaire","de":"M2 | Spezialisierung Dentalhypnose","en":"M2 | Dental Hypnosis Specialisation"}$json$::jsonb, $json${"fr":"Les connaissances et l’assurance nécessaires pour utiliser l’hypnose dans les soins bucco-dentaires.","de":"Fachwissen und Sicherheit für den Einsatz von Hypnose in der Zahnmedizin.","en":"The knowledge and confidence required to use hypnosis in oral and dental care."}$json$::jsonb, $json${"fr":"Ce module de spécialisation s’adresse exclusivement aux médecins-dentistes, hygiénistes dentaires et assistant·e·s dentaires ou prophylactiques. Il transmet les connaissances techniques et l’assurance nécessaires à la pratique de l’hypnose dentaire dans les soins bucco-dentaires.","de":"Dieses Spezialisierungsmodul richtet sich ausschliesslich an Zahnärztinnen und Zahnärzte, Dentalhygieniker·innen sowie zahnmedizinische und Prophylaxeassistent·innen. Es vermittelt Fachwissen und Sicherheit für Dentalhypnose in der Mund- und Zahnpflege.","en":"This specialist module is exclusively for dentists, dental hygienists, and dental or prophylaxis assistants. It provides the technical knowledge and confidence needed to practise dental hypnosis in oral care."}$json$::jsonb, $json${"fr":"Médecins-dentistes, hygiénistes dentaires et assistant·e·s dentaires ou prophylactiques.","de":"Zahnärzt·innen, Dentalhygieniker·innen sowie Dental- und Prophylaxeassistent·innen.","en":"Dentists, dental hygienists, and dental or prophylaxis assistants."}$json$::jsonb, $json${"fr":"3 jours · 24 heures","de":"3 Tage · 24 Stunden","en":"3 days · 24 hours"}$json$::jsonb, $json${"fr":"Fribourg","de":"Freiburg","en":"Fribourg"}$json$::jsonb, 1450, 'medical', true, 12),
('medical-hypnosis-clinical-m2', $json${"fr":"hypnose-medicale-clinique-m2","de":"medizinische-hypnose-klinik-m2","en":"medical-hypnosis-clinical-m2"}$json$::jsonb, $json${"fr":"M2 | Spécialisation Hypnose Clinique","de":"M2 | Spezialisierung klinische Hypnose","en":"M2 | Clinical Hypnosis Specialisation"}$json$::jsonb, $json${"fr":"Hypnose profonde, anesthésie hypnotique, ancrages, hypnose longue durée et gestion de l’analgésie.","de":"Tiefe Hypnose, hypnotische Anästhesie, Anker, Langzeithypnose und Analgesiemanagement.","en":"Deep hypnosis, hypnotic anaesthesia, anchoring, long-duration hypnosis and analgesia management."}$json$::jsonb, $json${"fr":"Ce module est consacré aux techniques avancées de l’hypnose médicale : état d’Esdaile, hypnose anesthésiante, ancrages, hypnose de longue durée et gestion des analgésies. Des cas réels et mises en situation préparent aux spécificités du milieu hospitalier.","de":"Dieses Modul behandelt fortgeschrittene medizinische Hypnosetechniken: Esdaile-Zustand, hypnotische Anästhesie, Anker, Langzeithypnose und Analgesiemanagement. Reale Fälle und Übungen bereiten auf Besonderheiten im Spital vor.","en":"This module covers advanced medical hypnosis: the Esdaile state, hypnotic anaesthesia, anchoring, long-duration hypnosis and analgesia management. Real cases and simulations prepare participants for hospital settings."}$json$::jsonb, $json${"fr":"Professionnel·le·s de la santé ayant suivi le module de base en hypnose médicale.","de":"Gesundheitsfachpersonen nach dem Grundlagenmodul medizinische Hypnose.","en":"Healthcare professionals who have completed the medical hypnosis foundation module."}$json$::jsonb, $json${"fr":"3 jours · 24 heures","de":"3 Tage · 24 Stunden","en":"3 days · 24 hours"}$json$::jsonb, $json${"fr":"Fribourg","de":"Freiburg","en":"Fribourg"}$json$::jsonb, 1450, 'medical', true, 13),
('medical-hypnosis-exam-m3', $json${"fr":"hypnose-medicale-supervision-examen-m3","de":"medizinische-hypnose-supervision-pruefung-m3","en":"medical-hypnosis-supervision-exam-m3"}$json$::jsonb, $json${"fr":"M3 | Supervision & examen","de":"M3 | Supervision & Prüfung","en":"M3 | Supervision & Exam"}$json$::jsonb, $json${"fr":"Une journée pour clarifier les difficultés de pratique, analyser les études de cas et passer l’examen pratique.","de":"Ein Tag für Praxisfragen, Fallanalysen und die praktische Prüfung.","en":"A day to resolve practice questions, analyse case studies and complete the practical exam."}$json$::jsonb, $json${"fr":"La journée de supervision et certification permet d’éliminer les incertitudes et d’aborder les difficultés rencontrées en pratique. Elle comprend la présentation et l’analyse des études de cas ainsi qu’un examen pratique vérifiant la maîtrise des techniques du cursus.","de":"Der Supervisions- und Zertifizierungstag klärt Unsicherheiten und Schwierigkeiten aus der Praxis. Er umfasst Präsentation und Analyse der Fallstudien sowie eine praktische Prüfung der im Lehrgang erworbenen Techniken.","en":"The supervision and certification day resolves uncertainties and difficulties encountered in practice. It includes presentation and analysis of case studies and a practical exam assessing mastery of the curriculum’s techniques."}$json$::jsonb, $json${"fr":"Participant·e·s au cursus de Praticien·ne en Hypnose Médicale ayant achevé les modules requis.","de":"Teilnehmende des Lehrgangs Medizinische Hypnose nach Abschluss der erforderlichen Module.","en":"Medical Hypnosis Practitioner participants who have completed the required modules."}$json$::jsonb, $json${"fr":"1 jour · 8 heures","de":"1 Tag · 8 Stunden","en":"1 day · 8 hours"}$json$::jsonb, $json${"fr":"Fribourg","de":"Freiburg","en":"Fribourg"}$json$::jsonb, 550, 'medical', true, 14),
('chronic-pain-hypnosis', $json${"fr":"douleurs-chroniques-hypnose","de":"chronische-schmerzen-hypnose","en":"chronic-pain-hypnosis"}$json$::jsonb, $json${"fr":"Douleurs chroniques & Hypnose","de":"Chronische Schmerzen & Hypnose","en":"Chronic Pain & Hypnosis"}$json$::jsonb, $json${"fr":"Des méthodes développées spécifiquement pour accompagner les personnes souffrant de douleurs persistantes.","de":"Methoden, die speziell für Menschen mit anhaltenden Schmerzen entwickelt wurden.","en":"Methods developed specifically to support people living with persistent pain."}$json$::jsonb, $json${"fr":"Contrairement à la douleur aiguë, la douleur chronique persiste et limite le rayon de vie. Cet atelier transmet des méthodes et techniques développées au Centre du dos de Bienne et Langenthal spécifiquement pour les personnes souffrant de douleurs chroniques.","de":"Anders als akute Schmerzen bleiben chronische Schmerzen bestehen und schränken das Leben ein. Der Workshop vermittelt Methoden, die im Rückenzentrum Biel und Langenthal speziell für Menschen mit chronischen Schmerzen entwickelt wurden.","en":"Unlike acute pain, chronic pain persists and restricts everyday life. This workshop teaches methods developed at the Biel and Langenthal Back Centre specifically for people living with chronic pain."}$json$::jsonb, $json${"fr":"Praticien·ne·s disposant d’une formation de base en hypnose.","de":"Praktiker·innen mit einer Grundausbildung in Hypnose.","en":"Practitioners with foundational hypnosis training."}$json$::jsonb, $json${"fr":"1 jour · 8 heures","de":"1 Tag · 8 Stunden","en":"1 day · 8 hours"}$json$::jsonb, $json${"fr":"Fribourg","de":"Freiburg","en":"Fribourg"}$json$::jsonb, 300, 'workshop', false, 15),
('birth-preparation', $json${"fr":"preparation-naissance","de":"geburtsvorbereitung","en":"birth-preparation"}$json$::jsonb, $json${"fr":"Préparation à la naissance","de":"Geburtsvorbereitung","en":"Birth Preparation"}$json$::jsonb, $json${"fr":"Accompagner la grossesse et la naissance avec davantage de sérénité, de confiance et de conscience.","de":"Schwangerschaft und Geburt mit mehr Ruhe, Vertrauen und Bewusstsein begleiten.","en":"Support pregnancy and birth with greater calm, confidence and awareness."}$json$::jsonb, $json${"fr":"Les croyances, mythes et influences culturelles peuvent perturber la perception de la naissance. Cet atelier considère la préparation à accueillir un bébé comme une expérience marquante, tant pendant la grossesse qu’au moment de la naissance, et propose des outils d’accompagnement hypnotique adaptés.","de":"Überzeugungen, Mythen und kulturelle Einflüsse können die Wahrnehmung der Geburt belasten. Dieser Workshop versteht die Vorbereitung auf ein Baby als prägende Erfahrung während Schwangerschaft und Geburt und vermittelt passende hypnotische Begleitwerkzeuge.","en":"Beliefs, myths and cultural influences can disrupt perceptions of birth. This workshop treats preparing to welcome a baby as a significant experience during both pregnancy and birth, and offers suitable hypnotic support tools."}$json$::jsonb, $json${"fr":"Praticien·ne·s en hypnose souhaitant accompagner les futurs parents.","de":"Hypnosepraktiker·innen, die werdende Eltern begleiten möchten.","en":"Hypnosis practitioners who want to support expectant parents."}$json$::jsonb, $json${"fr":"1 jour · 8 heures","de":"1 Tag · 8 Stunden","en":"1 day · 8 hours"}$json$::jsonb, $json${"fr":"Fribourg","de":"Freiburg","en":"Fribourg"}$json$::jsonb, 300, 'workshop', false, 16),
('weight-loss-hypnosis', $json${"fr":"perte-poids-hypnose","de":"gewichtsabnahme-hypnose","en":"weight-loss-hypnosis"}$json$::jsonb, $json${"fr":"Perte de poids & Hypnose","de":"Gewichtsabnahme & Hypnose","en":"Weight Loss & Hypnosis"}$json$::jsonb, $json${"fr":"Agir sur les croyances, émotions et habitudes alimentaires qui freinent une perte de poids durable.","de":"Überzeugungen, Emotionen und Essgewohnheiten bearbeiten, die nachhaltige Gewichtsabnahme behindern.","en":"Address beliefs, emotions and eating habits that stand in the way of lasting weight loss."}$json$::jsonb, $json${"fr":"Douce et non invasive, l’hypnose est souvent utilisée en complément d’un rééquilibrage alimentaire et d’un programme de remise en forme. Cet atelier aide à dépasser les croyances et émotions liées à l’alimentation, renforcer la motivation et favoriser des habitudes plus équilibrées.","de":"Hypnose ist sanft und nicht invasiv und ergänzt häufig Ernährungsumstellung und Bewegung. Der Workshop hilft, Überzeugungen und Emotionen rund ums Essen zu verändern, Motivation zu stärken und ausgewogenere Gewohnheiten zu fördern.","en":"Gentle and non-invasive, hypnosis is often used alongside dietary rebalancing and fitness. This workshop addresses beliefs and emotions around food, strengthens motivation and supports more balanced habits."}$json$::jsonb, $json${"fr":"Hypnothérapeutes souhaitant accompagner leurs client·e·s dans la perte de poids.","de":"Hypnosetherapeut·innen, die Klient·innen bei der Gewichtsabnahme begleiten möchten.","en":"Hypnotherapists who want to support clients with weight loss."}$json$::jsonb, $json${"fr":"1 jour · 8 heures","de":"1 Tag · 8 Stunden","en":"1 day · 8 hours"}$json$::jsonb, $json${"fr":"Fribourg","de":"Freiburg","en":"Fribourg"}$json$::jsonb, 300, 'workshop', false, 17),
('healthy-weight-nutrition-hypnosis', $json${"fr":"poids-sante-nutrition-hypnose","de":"gesundes-gewicht-ernaehrung-hypnose","en":"healthy-weight-nutrition-hypnosis"}$json$::jsonb, $json${"fr":"Poids santé, nutrition & hypnose","de":"Gesundes Gewicht, Ernährung & Hypnose","en":"Healthy Weight, Nutrition & Hypnosis"}$json$::jsonb, $json${"fr":"Associer nutrition holistique et hypnose pour un accompagnement personnalisé et durable du rapport à l’alimentation.","de":"Ganzheitliche Ernährung und Hypnose für eine persönliche, nachhaltige Begleitung des Essverhaltens verbinden.","en":"Combine holistic nutrition and hypnosis for personalised, lasting support around eating."}$json$::jsonb, $json${"fr":"Face au manque d’outils pratiques, cet atelier associe les connaissances d’une diététicienne et d’une hypnothérapeute. Il combine nutrition holistique et hypnose afin d’offrir un suivi personnalisé et de soutenir durablement le rapport des client·e·s à l’alimentation.","de":"Dieser Workshop verbindet das Wissen einer Ernährungsberaterin und einer Hypnosetherapeutin. Ganzheitliche Ernährung und Hypnose ermöglichen eine individuelle Begleitung und eine nachhaltige Veränderung der Beziehung zum Essen.","en":"This workshop combines the expertise of a dietitian and a hypnotherapist. It brings holistic nutrition and hypnosis together to offer personalised support and sustainably improve clients’ relationship with food."}$json$::jsonb, $json${"fr":"Hypnothérapeutes et professionnel·le·s de la nutrition ou de l’accompagnement.","de":"Hypnosetherapeut·innen sowie Fachpersonen aus Ernährung und Beratung.","en":"Hypnotherapists and nutrition or helping professionals."}$json$::jsonb, $json${"fr":"1 jour · 8 heures","de":"1 Tag · 8 Stunden","en":"1 day · 8 hours"}$json$::jsonb, $json${"fr":"Fribourg","de":"Freiburg","en":"Fribourg"}$json$::jsonb, 450, 'workshop', false, 18),
('sensory-anchors-hypnosis', $json${"fr":"ancrages-sensoriels-hypnose","de":"sensorische-anker-hypnose","en":"sensory-anchors-hypnosis"}$json$::jsonb, $json${"fr":"Ancrages sensoriels & Hypnose","de":"Sensorische Anker & Hypnose","en":"Sensory Anchors & Hypnosis"}$json$::jsonb, $json${"fr":"Associer un état émotionnel, mental ou physique à un stimulus sensoriel pour mieux y accéder en hypnose.","de":"Emotionale, mentale oder körperliche Zustände mit Sinnesreizen verknüpfen und hypnotisch nutzbar machen.","en":"Link an emotional, mental or physical state to a sensory stimulus for easier access in hypnosis."}$json$::jsonb, $json${"fr":"Un ancrage sensoriel associe une expérience émotionnelle, un état mental ou physique à une image, un son, une odeur ou une sensation tactile. En hypnose, ce mécanisme naturel est amplifié pour faciliter l’accès à la détente, la confiance, la gestion des émotions, du stress ou de la performance.","de":"Ein sensorischer Anker verbindet ein emotionales, mentales oder körperliches Erleben mit einem Bild, Geräusch, Geruch oder einer Berührung. In Hypnose wird dieser natürliche Mechanismus verstärkt, um Entspannung, Vertrauen, Emotions- und Stressregulation oder Leistung leichter zugänglich zu machen.","en":"A sensory anchor links an emotional, mental or physical experience to an image, sound, smell or touch. Hypnosis amplifies this natural mechanism to make relaxation, confidence, emotional and stress regulation, or performance easier to access."}$json$::jsonb, $json${"fr":"Praticien·ne·s en hypnose souhaitant enrichir leur palette d’outils sensoriels.","de":"Hypnosepraktiker·innen, die ihr Repertoire um sensorische Werkzeuge erweitern möchten.","en":"Hypnosis practitioners who want to expand their sensory toolkit."}$json$::jsonb, $json${"fr":"1 jour · 8 heures","de":"1 Tag · 8 Stunden","en":"1 day · 8 hours"}$json$::jsonb, $json${"fr":"Fribourg","de":"Freiburg","en":"Fribourg"}$json$::jsonb, 300, 'workshop', false, 19),
('stripe-payment-test', $json${"fr":"test-paiement-stripe","de":"stripe-zahlungstest","en":"stripe-payment-test"}$json$::jsonb, $json${"fr":"Test interne — paiement Stripe","de":"Interner Test — Stripe-Zahlung","en":"Internal test — Stripe payment"}$json$::jsonb, $json${"fr":"Session interne à 10 CHF pour vérifier le paiement Stripe en conditions réelles. Ce n’est pas une formation; le montant sera remboursé.","de":"Interner 10-CHF-Termin zur Prüfung einer echten Stripe-Zahlung. Keine Ausbildung; der Betrag wird rückerstattet.","en":"Internal CHF 10 session to verify a live Stripe payment. This is not a training course; the amount will be refunded."}$json$::jsonb, $json${"fr":"Cette entrée existe uniquement pour tester le checkout Stripe, le webhook et l’e-mail de confirmation avec un montant de 10 francs. Elle ne correspond à aucune formation réelle et le paiement sera remboursé après le test.","de":"Dieser Eintrag dient nur dazu, Stripe-Checkout, Webhook und Bestätigungsmail mit 10 Franken zu prüfen. Es handelt sich um keine echte Ausbildung; die Zahlung wird nach dem Test rückerstattet.","en":"This entry exists only to test Stripe Checkout, the webhook and the confirmation email with a 10-franc charge. It is not a real course, and the payment will be refunded after the test."}$json$::jsonb, $json${"fr":"Réservé à l’équipe MHP pour un test de paiement. Merci de ne pas vous inscrire.","de":"Nur für das MHP-Team zum Zahlungstest. Bitte nicht buchen.","en":"Reserved for the MHP team’s payment test. Please do not enrol."}$json$::jsonb, $json${"fr":"Test paiement","de":"Zahlungstest","en":"Payment test"}$json$::jsonb, $json${"fr":"Fribourg","de":"Freiburg","en":"Fribourg"}$json$::jsonb, 10, 'workshop', true, 20)
